\set ON_ERROR_STOP on
BEGIN;
CREATE TEMP TABLE taxonomy_checks(label text);
CREATE FUNCTION pg_temp.taxonomy_assert(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',label; END IF; INSERT INTO pg_temp.taxonomy_checks VALUES(label); END; $$;
CREATE FUNCTION pg_temp.taxonomy_denied(statement text,code text,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE statement; EXCEPTION WHEN OTHERS THEN IF SQLSTATE=code THEN PERFORM pg_temp.taxonomy_assert(true,label);RETURN;END IF;RAISE EXCEPTION 'Unexpected % (%): %',SQLSTATE,label,SQLERRM; END;RAISE EXCEPTION 'Unexpected acceptance: %',label;END; $$;
GRANT INSERT ON taxonomy_checks TO authenticated,anon;
INSERT INTO auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
SELECT id,'authenticated','authenticated',id::text||'@local.invalid','',now(),'{"provider":"email","providers":["email"]}','{"first_name":"LOCAL TAXONOMY FIXTURE","birth_date":"2000-01-01"}',now(),now() FROM unnest(ARRAY['a5700000-0000-4000-8000-000000000001'::uuid,'a5700000-0000-4000-8000-000000000002'::uuid]) id;
UPDATE public.profiles SET role='admin' WHERE id='a5700000-0000-4000-8000-000000000001';
DO $tests$
DECLARE chapter jsonb; skill jsonb; other jsonb; unused jsonb; updated jsonb; stale text; token text; before_count bigint; draft jsonb; saved_definition jsonb; cvalue jsonb:='{"name":"LOCAL TAXONOMY CHAPTER","aliases":["LOCAL REFERENCED ALIAS"],"emoji":"🧮","order_index":990}';
BEGIN
 PERFORM set_config('request.jwt.claim.sub','a5700000-0000-4000-8000-000000000002',true);
 PERFORM set_config('request.jwt.claims','{"sub":"a5700000-0000-4000-8000-000000000002","is_anonymous":false}',true);
 SET LOCAL ROLE authenticated;
 PERFORM pg_temp.taxonomy_denied('SELECT public.admin_list_taxonomy(''chapter'')','42501','student cannot read admin taxonomy');
 PERFORM pg_temp.taxonomy_denied('SELECT public.admin_mutate_taxonomy(''chapter'',''save'',NULL,NULL,''{"name":"FORGED"}'')','42501','student cannot mutate taxonomy');
 SET LOCAL ROLE anon;
 PERFORM pg_temp.taxonomy_denied('SELECT public.admin_list_taxonomy(''chapter'')','42501','anon cannot execute taxonomy RPC');
 RESET ROLE;
 PERFORM set_config('request.jwt.claim.sub','a5700000-0000-4000-8000-000000000001',true);
 PERFORM set_config('request.jwt.claims','{"sub":"a5700000-0000-4000-8000-000000000001","is_anonymous":true}',true);
 SET LOCAL ROLE authenticated;
 PERFORM pg_temp.taxonomy_denied('SELECT public.admin_list_taxonomy(''chapter'')','42501','anonymous admin is refused');
 RESET ROLE;
 PERFORM set_config('request.jwt.claims','{"sub":"a5700000-0000-4000-8000-000000000001","is_anonymous":false}',true);
 SET LOCAL ROLE authenticated;
 PERFORM pg_temp.taxonomy_assert((public.admin_list_taxonomy('chapter')->>'total')::integer>0,'admin can list existing chapters');
 chapter:=public.admin_mutate_taxonomy('chapter','save',NULL,NULL,cvalue)->'item';
 PERFORM pg_temp.taxonomy_assert(chapter->'value'->>'name'=cvalue->>'name' AND chapter->'value'->>'emoji'='🧮','chapter is created with name emoji order and alias');
 PERFORM pg_temp.taxonomy_assert(jsonb_array_length(public.admin_list_taxonomy('chapter','LOCAL REFERENCED ALIAS')->'items')=1,'literal alias search works');
 PERFORM pg_temp.taxonomy_denied(format('SELECT public.admin_mutate_taxonomy(''chapter'',''save'',NULL,NULL,%L)',cvalue),'23505','duplicate chapter tokens refused');
 PERFORM pg_temp.taxonomy_denied('INSERT INTO public.chapters(name,order_index) VALUES(''DIRECT'',999)','42501','direct API table mutation denied');
 PERFORM pg_temp.taxonomy_denied('SELECT public.admin_mutate_taxonomy(''chapter'',''save'',NULL,NULL,''{"name":"X","aliases":[],"emoji":"","order_index":1,"production":true}'')','22023','unknown chapter fields refused in SQL');
 stale:=chapter->>'fingerprint';
 updated:=public.admin_mutate_taxonomy('chapter','save',chapter->>'id',stale,jsonb_set(cvalue,'{order_index}','991'))->'item';
 chapter:=public.admin_mutate_taxonomy('chapter','save',chapter->>'id',updated->>'fingerprint',cvalue)->'item';
 PERFORM pg_temp.taxonomy_assert(chapter->>'fingerprint'<>stale,'monotone revision survives edit then revert');
 PERFORM pg_temp.taxonomy_denied(format('SELECT public.admin_mutate_taxonomy(''chapter'',''save'',%L,%L,%L)',chapter->>'id',stale,cvalue),'40001','stale save refused after edit and revert');
 other:=public.admin_mutate_taxonomy('chapter','save',NULL,NULL,'{"name":"LOCAL OTHER TAXONOMY","aliases":[],"emoji":"","order_index":991}')->'item';
 skill:=public.admin_mutate_taxonomy('competence','save',NULL,NULL,jsonb_build_object('id','local-taxonomy-skill','name','LOCAL TAXONOMY SKILL','chapter_id',chapter->>'id','max_points',10))->'item';
 PERFORM pg_temp.taxonomy_assert(skill->'value'->>'id'='local-taxonomy-skill' AND skill->'value'->>'max_points'='10','competence stable identity and max points created');
 PERFORM pg_temp.taxonomy_assert((public.admin_list_taxonomy('competence','',(chapter->>'id')::uuid)->>'total')::integer=1,'chapter filter returns linked skill');
 chapter:=public.admin_list_taxonomy('chapter','LOCAL TAXONOMY CHAPTER')->'items'->0;
 PERFORM pg_temp.taxonomy_assert(chapter->'usage'->>'competences'='1','chapter dependency count includes child competence');
 PERFORM pg_temp.taxonomy_denied(format('SELECT public.admin_mutate_taxonomy(''chapter'',''delete'',%L,%L,NULL)',chapter->>'id',chapter->>'fingerprint'),'23503','chapter cascade deletion blocked');
 PERFORM pg_temp.taxonomy_denied(format('SELECT public.admin_mutate_taxonomy(''competence'',''save'',%L,%L,%L)',skill->>'id',skill->>'fingerprint',(skill->'value')||'{"id":"changed-id"}'),'22023','competence identifier immutable');
 PERFORM pg_temp.taxonomy_denied(format('SELECT public.admin_mutate_taxonomy(''competence'',''save'',NULL,NULL,%L)',jsonb_build_object('id','missing-chapter','name','MISSING','chapter_id','a5790000-0000-4000-8000-000000000000','max_points',10)),'23503','missing chapter refused');
 draft:=public.admin_save_exercise_draft(NULL,NULL,NULL,jsonb_build_object('schemaVersion',5,'kind','composed','title','LOCAL TAXONOMY EXERCISE','catalogue',jsonb_build_object('chapter','LOCAL REFERENCED ALIAS','skills',jsonb_build_array('LOCAL TAXONOMY SKILL')),'generation',jsonb_build_object('schemaVersion',5,'definitions','[]'::jsonb,'constraints','[]'::jsonb,'maxAttempts',100,'maxDraws',1000),'variables','[]'::jsonb,'elements','[]'::jsonb));
 SELECT definition INTO saved_definition FROM public.exercise_versions WHERE id=(draft->>'versionId')::uuid;
 chapter:=public.admin_list_taxonomy('chapter','LOCAL TAXONOMY CHAPTER')->'items'->0;
 skill:=public.admin_list_taxonomy('competence','local-taxonomy-skill')->'items'->0;
 PERFORM pg_temp.taxonomy_assert(chapter->'usage'->>'exercises'='1' AND skill->'usage'->>'revisions'='1','canonical references included without exposing answers');
 PERFORM pg_temp.taxonomy_assert(chapter->'usage'->'exerciseIds' @> jsonb_build_array(draft->>'exerciseId'),'associated exercise ID is losslessly linked');
 PERFORM pg_temp.taxonomy_denied(format('SELECT public.admin_mutate_taxonomy(''chapter'',''save'',%L,%L,%L)',chapter->>'id',chapter->>'fingerprint',cvalue||'{"aliases":[]}'),'23503','referenced alias cannot be removed');
 chapter:=public.admin_mutate_taxonomy('chapter','save',chapter->>'id',chapter->>'fingerprint',cvalue||'{"name":"RENAMED LOCAL CHAPTER"}')->'item';
 PERFORM pg_temp.taxonomy_assert(chapter->'value'->'aliases' @> '["LOCAL TAXONOMY CHAPTER"]','renaming chapter preserves former name');
 PERFORM pg_temp.taxonomy_assert((SELECT definition=saved_definition FROM public.exercise_versions WHERE id=(draft->>'versionId')::uuid),'taxonomy update never rewrites exercise definition');
 PERFORM pg_temp.taxonomy_denied(format('SELECT public.admin_mutate_taxonomy(''competence'',''save'',%L,%L,%L)',skill->>'id',skill->>'fingerprint',(skill->'value')||'{"name":"RENAMED SKILL"}'),'23503','referenced skill name cannot be changed');
 PERFORM pg_temp.taxonomy_denied(format('SELECT public.admin_mutate_taxonomy(''competence'',''save'',%L,%L,%L)',skill->>'id',skill->>'fingerprint',jsonb_set(skill->'value','{chapter_id}',other->'id')),'23503','referenced skill cannot change chapter');
 PERFORM pg_temp.taxonomy_denied(format('SELECT public.admin_mutate_taxonomy(''competence'',''delete'',%L,%L,NULL)',skill->>'id',skill->>'fingerprint'),'23503','referenced skill cannot be deleted');
 unused:=public.admin_mutate_taxonomy('competence','save',NULL,NULL,jsonb_build_object('id','local-unused-skill','name','LOCAL UNUSED SKILL','chapter_id',chapter->>'id','max_points',10))->'item';
 unused:=public.admin_mutate_taxonomy('competence','save',unused->>'id',unused->>'fingerprint',jsonb_set(unused->'value','{chapter_id}',other->'id')||'{"max_points":15}')->'item';
 PERFORM pg_temp.taxonomy_assert(unused->'value'->>'chapter_id'=other->>'id' AND unused->'value'->>'max_points'='15','unused competence can move and update points');
 RESET ROLE;
 INSERT INTO public.user_competence_scores(user_id,competence_id,points) VALUES('a5700000-0000-4000-8000-000000000002','local-unused-skill',1);
 SET LOCAL ROLE authenticated;
 unused:=public.admin_list_taxonomy('competence','local-unused-skill')->'items'->0;
 PERFORM pg_temp.taxonomy_assert(unused->'usage'->>'scores'='1','score count includes another user without revealing identity');
 PERFORM pg_temp.taxonomy_denied(format('SELECT public.admin_mutate_taxonomy(''competence'',''delete'',%L,%L,NULL)',unused->>'id',unused->>'fingerprint'),'23503','score cascade deletion blocked');
 updated:=public.admin_mutate_taxonomy('chapter','save',NULL,NULL,'{"name":"LOCAL FLASHCARD ONLY","aliases":[],"emoji":"","order_index":995}')->'item';
 RESET ROLE;
 INSERT INTO public.flashcards(chapter,question,answer) VALUES('LOCAL FLASHCARD ONLY','Synthetic fixture','Synthetic answer');
 SET LOCAL ROLE authenticated;
 updated:=public.admin_list_taxonomy('chapter','LOCAL FLASHCARD ONLY')->'items'->0;
 PERFORM pg_temp.taxonomy_assert(updated->'usage'->>'flashcards'='1' AND updated->'usage'->>'competences'='0','flashcard-only chapter dependency is counted');
 PERFORM pg_temp.taxonomy_denied(format('SELECT public.admin_mutate_taxonomy(''chapter'',''delete'',%L,%L,NULL)',updated->>'id',updated->>'fingerprint'),'23503','flashcard-only chapter deletion blocked');
 updated:=public.admin_mutate_taxonomy('competence','save',NULL,NULL,jsonb_build_object('id','local-legacy-only','name','LOCAL LEGACY ONLY','chapter_id',other->>'id','max_points',10))->'item';
 RESET ROLE;
 INSERT INTO public.exercises(title,chapter,content) VALUES('LOCAL LEGACY TAXONOMY FIXTURE','UNRELATED CHAPTER','{"historicalReference":"local-legacy-only"}');
 SET LOCAL ROLE authenticated;
 updated:=public.admin_list_taxonomy('competence','local-legacy-only')->'items'->0;
 PERFORM pg_temp.taxonomy_assert(updated->'usage'->>'exercises'='1' AND updated->'usage'->>'revisions'='0','legacy JSON reference is detected without canonical conversion');
 PERFORM pg_temp.taxonomy_denied(format('SELECT public.admin_mutate_taxonomy(''competence'',''delete'',%L,%L,NULL)',updated->>'id',updated->>'fingerprint'),'23503','legacy-only competence deletion blocked');
 unused:=public.admin_mutate_taxonomy('competence','save',NULL,NULL,jsonb_build_object('id','local-deletable-skill','name','LOCAL DELETABLE SKILL','chapter_id',other->>'id','max_points',10))->'item';
 PERFORM pg_temp.taxonomy_assert(public.admin_mutate_taxonomy('competence','delete',unused->>'id',unused->>'fingerprint',NULL)->>'action'='deleted','only unused synthetic competence is deleted');
 unused:=public.admin_mutate_taxonomy('chapter','save',NULL,NULL,'{"name":"LOCAL DELETABLE CHAPTER","aliases":[],"emoji":"","order_index":999}')->'item';
 PERFORM pg_temp.taxonomy_assert(public.admin_mutate_taxonomy('chapter','delete',unused->>'id',unused->>'fingerprint',NULL)->>'action'='deleted','only unused synthetic chapter is deleted');
 PERFORM pg_temp.taxonomy_assert(NOT EXISTS(SELECT 1 FROM public.admin_taxonomy_events WHERE actor_id<>'a5700000-0000-4000-8000-000000000001'),'audit actor always comes from checked Auth');
 SELECT count(*) INTO before_count FROM public.admin_taxonomy_events;
 PERFORM pg_temp.taxonomy_denied(format('SELECT public.admin_mutate_taxonomy(''chapter'',''delete'',%L,%L,NULL)',chapter->>'id',chapter->>'fingerprint'),'23503','dependency refused at execution, not just UI');
 PERFORM pg_temp.taxonomy_assert((SELECT count(*)=before_count FROM public.admin_taxonomy_events),'failed mutation leaves no audit event');
 RESET ROLE;
 UPDATE public.profiles SET role='user' WHERE id='a5700000-0000-4000-8000-000000000001';
 SET LOCAL ROLE authenticated;
 PERFORM pg_temp.taxonomy_denied('SELECT public.admin_list_taxonomy(''chapter'')','42501','role revocation takes effect immediately');
 RESET ROLE;
END; $tests$;
SELECT jsonb_build_object('result','PASS','taxonomyAssertions',count(*)) FROM pg_temp.taxonomy_checks;
ROLLBACK;
